    // teach one, redeclare that one, complete. Once teaching has begun the
    // declared set may grow but never lose or reword an entry — grounding
    // receipts also cite these strings verbatim, so a rewrite would silently
    // invalidate the basis of every question already asked.
    const retired = section.objectives.filter((objective) => !objectives.includes(objective));
    if (section.status !== "not-started" && retired.length > 0) {
      throw new Error(
        `Scholar Learn objectives are fixed once teaching begins, and completion requires covering all of them. `
        + `This call drops ${retired.length} already-declared objective(s): ${retired.join("; ")}. `
        + `Include them again — add to coveredObjectives as you teach them. To state one more clearly, keep the original text and append the clearer version as a new objective.`,
      );
    }
    section.objectives = objectives;
    const sourceCoverage = params.coverageUpdates ? updateCoverageEvidence(section.learnQuality?.coverage || [], params.coverageUpdates) : params.sourceCoverage;
    if (sourceCoverage !== undefined) {
      if (section.status === "complete" && JSON.stringify(sourceCoverage) !== JSON.stringify(section.learnQuality?.coverage)) throw new Error("Practice cannot adopt or replace the completed section's source coverage contract.");
      const rawCoverage: unknown = sourceCoverage;
      if (!isSourceCoverageLedger(rawCoverage)) {
        const invalid = Array.isArray(rawCoverage) ? rawCoverage.flatMap((item, index) =>
          isSourceCoverageItem(item) ? [] : [`${index + 1}${typeof item?.id === "string" ? ` (${item.id})` : ""}`]) : [];
        throw new Error(`Nothing saved. Invalid sourceCoverage ${invalid.length ? `item(s): ${invalid.join(", ")}` : "checklist (expected an array with unique IDs)"}. Each item needs id, kind, description, sourcePages and objective. Optional IDs must be nonempty identifiers; optional evidence must be a nonempty exact passage. Omit unused optional fields. Equation and snapshot references may accompany any item, but must identify content rendered in that lesson at completion. Correct those fields and retry; do not discard the lesson or change its objectives.`);
      }
      const issues = sourceCoverageIssues(sourceCoverage, { ...section, lessons: [] });
      if (issues.length) throw new Error(`Repair the source coverage plan: ${issues.join("; ")}`);
      section.learnQuality ||= { version: 1, coverage: [], reviews: [] };
      section.learnQuality.coverage = sourceCoverage;
    }
    if (params.objectiveChecks !== undefined) {
      if (!isObjectiveChecks(params.objectiveChecks) || params.objectiveChecks.some(item => !objectives.includes(item.objective))) throw new Error("objectiveChecks must map declared objectives to nonempty conceptual/application/computation/discrimination checks.");
      const changed = (section.objectiveChecks || []).some(old => !params.objectiveChecks!.some(next => next.objective === old.objective && old.checks.every(kind => next.checks.includes(kind))));
      if (changed && !editorial) throw new Error("Keep existing objective checks; do not lower the mastery requirements after teaching starts.");
      if (section.status === "complete" && JSON.stringify(params.objectiveChecks) !== JSON.stringify(section.objectiveChecks)) throw new Error("Practice cannot change the completed section's objective checks.");
      section.objectiveChecks = params.objectiveChecks;
    }
    const checks = params.requiredChecks === undefined
      ? requiredChecks(editorial && params.objectiveChecks ? params.objectiveChecks.flatMap(item => item.checks) : section.requiredChecks) : requiredChecks(params.requiredChecks);
    const droppedChecks = section.requiredChecks.filter((kind) => !checks.includes(kind));
    if (!editorial && section.status !== "not-started" && droppedChecks.length > 0) {
      throw new Error(`Scholar Learn checks are fixed once teaching begins. Keep these required checks: ${droppedChecks.join(", ")}.`);
    }
    section.requiredChecks = requiredChecks([...checks, ...(section.objectiveChecks || []).flatMap(item => item.checks)]);
    if (synthesis) section.synthesis = synthesis;
    section.keyPoints = compactStrings([...(editorial && params.keyPoints !== undefined ? [] : section.keyPoints), ...keyPoints, ...(params.lesson?.keyPoints || [])]);
    if (params.misconceptions !== undefined) section.misconceptions = compactStrings(params.misconceptions);
    if (params.lesson) saveLesson(section, state, params.lesson, config);
    if (params.lessonPatch) patchLesson(section, state, params.lessonPatch, config);
    const taught = compactStrings(validLessonEntries(section, state.source.fingerprint.sha256).flatMap(entry => entry.lesson!.objectives));
    if (params.coveredObjectives !== undefined && covered.some(objective => !taught.includes(objective)) && section.status !== "complete") {
      throw new Error("Coverage needs an explicitly saved explanation for each objective; a summary or label cannot mark it taught. Save notes.lesson first.");
    }
    if (section.status !== "complete") section.coveredObjectives = taught;
    if (params.findingResponses?.length && section.learnQuality) {
      const existing = new Map((section.learnQuality.responses || []).map(r => [r.key, r]));
      for (const resp of params.findingResponses) existing.set(resp.key, resp);
      section.learnQuality.responses = [...existing.values()];
    }
    if (params.lessonComplete && !deferCommit) commitLesson(section, state);
    recomputeProgress(state, section);
  });
  const section = findSection(mutation.book, sectionId)!;
  const progress = section.learnQuality && !lessonReady(section, mutation.book.source.fingerprint.sha256)
    ? `Draft saved; lesson preparation is still in progress. ${!section.synthesis || !section.keyPoints.length ? "Save the recap and key points. " : ""}${!section.objectiveChecks?.length ? "Save the objectiveChecks plan. " : ""}When the explanation and exact evidence links are complete, submit lessonComplete for review. Learner mastery checks come after lesson approval.`
    : sectionProgressMessage(section);
  return toolResult("notes", `Saved ${params.lesson || params.lessonPatch ? "instructional explanation" : "notes"} for ${sectionLabel(mutation.book, section)}.${params.lessonComplete ? deferCommit ? " Draft saved; independent review pending." : " Full lesson committed." : ""} Status: ${section.status}. ${progress}`, { bookId: book.id, sectionId });
}

