    if (this.loadingTarget) this.loadingTarget.kind = "response";
    this.loadingFailed = false;
    this.loadingProblem = undefined;
    this.loadingRound = 0;
    this.loadingRepair = this.loadingNeedsWriting = false;
    this.loading.bindSignal(ctx.signal);
